        short = name.replace("arm64_op_", "")
        impl.append(f"/* 发射 {desc} */")
        impl.append(f"ARM64Instr* arm64_emit_{short}(ARM64Function* func, ARM64Register rd, ARM64Register rn, ARM64Register rm, int imm) {{")
