        impl.append(f"    instr->next = NULL;")
        impl.append(f"    if (func->last) {{")
        impl.append(f"        func->last->next = instr;")
        impl.append(f"        instr->prev = func->last;")
        impl.append(f"    }} else {{")
        impl.append(f"        func->first = instr;")
        impl.append(f"    }}")
        impl.append(f"    func->last = instr;")
        impl.append(f"    func->instr_count++;")
        impl.append(f"    return instr;")
        impl.append(f"}}")
