def gen_runtime_objects():
    global total
    
    obj_types = []
    for i in range(200):
        obj_types.append((f"OBJ_TYPE_{i:03d}", f"对象类型 {i}"))
    
    lines = []
    lines.append("/*")
    lines.append(" * Aurora 运行时 - 对象系统")
    lines.append(" * 支持 200+ 对象类型")
    lines.append(" */")
    lines.append("")
    lines.append("#ifndef AURORA_RUNTIME_OBJECTS_H")
    lines.append("#define AURORA_RUNTIME_OBJECTS_H")
    lines.append("")
    lines.append("#include <stdio.h>")
    lines.append("#include <stdlib.h>")
    lines.append("#include <string.h>")
    lines.append("")
    lines.append("/* 对象类型 */")
    lines.append("typedef enum {")
    for name, desc in obj_types:
        lines.append(f"    {name}, /* {desc} */")
    lines.append("    OBJ_TYPE_COUNT")
    lines.append("} ObjectType;")
    lines.append("")
    lines.append("/* 对象头 */")
    lines.append("typedef struct ObjectHeader {")
    lines.append("    ObjectType type;")
    lines.append("    int ref_count;")
    lines.append("    int hash;")
    lines.append("    size_t size;")
    lines.append("    struct ObjectHeader* next;")
    lines.append("    struct ObjectHeader* prev;")
    lines.append("    int gc_color;")
    lines.append("    int gc_generation;")
    lines.append("    int gc_age;")
    lines.append("    void* gc_forward;")
    lines.append("    int flags;")
    lines.append("} ObjectHeader;")
    lines.append("")
    lines.append("/* 对象 */")
    lines.append("typedef struct Object {")
    lines.append("    ObjectHeader header;")
    lines.append("    union {")
    lines.append("        struct { char* data; int length; } string;")
    lines.append("        struct { void** data; int length; int capacity; } array;")
    lines.append("        struct { void* buckets; int size; int capacity; } dict;")
    lines.append("        struct { void* code; int arg_count; int local_count; } func;")
    lines.append("        struct { void* native_func; void* data; } native;")
    lines.append("        struct { void* env; void* func; } closure;")
    lines.append("        struct { void* iter; void* collection; } iterator;")
    lines.append("        struct { void* frame; void* code; } generator;")
    lines.append("        struct { void* state; void* result; void* callbacks; } promise;")
    lines.append("        struct { void* state; void* result; } future;")
    lines.append("        struct { void* buffer; int capacity; int count; } channel;")
    lines.append("        struct { void* context; void* stack; int state; } coroutine;")
    lines.append("        struct { void* thread; void* stack; int state; } thread;")
    lines.append("        struct { void* mutex; int locked; } mutex;")
    lines.append("        struct { void* cond; void* mutex; } cond;")
    lines.append("        struct { void* sem; int count; int max; } semaphore;")
    lines.append("        struct { void* barrier; int count; int waiting; } barrier;")
    lines.append("        struct { void* file; char* path; int mode; } file;")
    lines.append("        struct { void* socket; int fd; int type; } socket;")
    lines.append("        struct { void* buffer; int position; int limit; int capacity; } stream;")
    lines.append("        struct { void* data; int position; int limit; int capacity; } buffer;")
    lines.append("        struct { void* regex; char* pattern; int flags; } regex;")
    lines.append("        struct { void* root; char* text; } json;")
